21	/// Translate the conversation into Anthropic's request shape.
22	///
23	/// `system` is `None` when no `Item::System` has non-blank text. `messages`
24	/// is always an array. Text parts that are empty or whitespace only, and
25	/// messages left with no blocks, are dropped because the API rejects them.
26	pub(crate) fn translate_messages(items: &[Item]) -> TranslatedMessages {
27	    let mut system_text = String::new();
28	    let mut messages: Vec<Value> = Vec::new();
29	    let mut pending_tool_use: Vec<Value> = Vec::new();
30	    let mut pending_tool_results: Vec<Value> = Vec::new();
31	    let mut last_item_dropped = false;
32	
33	    fn flush_pending_assistant(messages: &mut Vec<Value>, pending: &mut Vec<Value>) {
34	        if !pending.is_empty() {
35	            messages.push(json!({
36	                "role": "assistant",
37	                "content": std::mem::take(pending),
38	            }));
39	        }
40	    }
41	
42	    fn flush_pending_user(messages: &mut Vec<Value>, pending: &mut Vec<Value>) {
43	        if !pending.is_empty() {
44	            messages.push(json!({
45	                "role": "user",
46	                "content": std::mem::take(pending),
47	            }));
48	        }
49	    }
50	
51	    for item in items {
52	        match item {
53	            Item::System { content } => {
54	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
55	                flush_pending_user(&mut messages, &mut pending_tool_results);
56	                if !system_text.is_empty() {
57	                    system_text.push('\n');
58	                }
59	                system_text.push_str(&text_of(content));
60	            }
61	            Item::UserMessage { content } => {
62	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
63	                // Pending tool_results go at the front of this user turn.
64	                let mut blocks: Vec<Value> = std::mem::take(&mut pending_tool_results);
65	                blocks.extend(user_blocks(content).as_array().unwrap().iter().cloned());
66	                last_item_dropped = blocks.is_empty();
67	                if !blocks.is_empty() {
68	                    messages.push(json!({"role": "user", "content": blocks}));
69	                }
70	            }
71	            Item::AssistantMessage { content, agent: _ } => {
72	                let blocks = assistant_blocks(content);
73	                // An assistant item with no blocks acts as if it were absent:
74	                // it flushes nothing (so an open tool round stays whole) and
75	                // leaves the flag as it is (a drop of the user turn before
76	                // it still counts). A kept assistant message ends the drop.
77	                if !blocks.as_array().unwrap().is_empty() {
78	                    flush_pending_assistant(&mut messages, &mut pending_tool_use);
79	                    flush_pending_user(&mut messages, &mut pending_tool_results);
80	                    last_item_dropped = false;
81	                    messages.push(json!({"role": "assistant", "content": blocks}));
82	                }
83	            }
84	            Item::ToolCall {
85	                call_id,
86	                name,
87	                args,
88	            } => {
89	                last_item_dropped = false;
90	                // A new tool_use follows any results already seen. Close
91	                // that user turn first only when the last assistant round is
92	                // fully answered; otherwise the call joins that round.
93	                if round_is_answered(&messages, &pending_tool_results) {
94	                    flush_pending_user(&mut messages, &mut pending_tool_results);
95	                }
96	                let block = json!({
97	                    "type": "tool_use",
98	                    "id": call_id,
99	                    "name": name,
100	                    "input": args,
101	                });
102	                if let Some(last) = messages.last_mut().filter(|m| m["role"] == "assistant") {
103	                    last["content"].as_array_mut().unwrap().push(block);
104	                } else {
105	                    pending_tool_use.push(block);
106	                }
107	            }
108	            Item::ToolResult { call_id, content } => {
109	                last_item_dropped = false;
110	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
111	                pending_tool_results.push(json!({
112	                    "type": "tool_result",
113	                    "tool_use_id": call_id,
114	                    "content": text_of(content),
115	                }));
116	            }
117	            _ => {
118	                tracing::warn!(
