192	    }
193	    let model = builder.build().unwrap();
194	    let req = req_with(messages, |r| {
195	        r.model_settings.max_output_tokens = Some(64);
196	        if with_tool {
197	            r.tools = vec![ToolDef {
198	                name: "ping".to_owned(),
199	                description: "Ping.".to_owned(),
200	                schema: serde_json::json!({"type": "object"}),
201	            }];
202	        }
203	    });
204	    let mut s = model.invoke(req, CancellationToken::new()).await.unwrap();
205	    while let Some(ev) = s.next().await {
206	        if let Err(e) = ev {
207	            panic!("stream error: {e:?}");
208	        }
209	    }
210	}
